using System.Numerics;
using System.Reflection;
using ByteEngine.Core;
using ByteEngine.Core.Characters;
using ByteEngine.Core.Gameplay;
using ByteEngine.Core.Graphics;
using ByteEngine.Core.InputSystem;
using ByteEngine.Core.Scene;
using KarlsonDemo.Plugin;
internal static class MiningCampVerify
{
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS CAMP "+text);}
 public static void Run(Scene scene,MiningOperation3D op)
 {
  byte[] hash=System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(Program.Root+"/Scenes/Main.bytescene"));var host=new SceneManager();host.LoadScene(scene);
  var player=scene.FindGameObject(op.PlayerObjectId)!;var camp=player.GetComponent<MiningCampLayout3D>()!;var ui=scene.GameObjects.SelectMany(o=>o.Components).OfType<MiningBusinessUi3D>().Single();var planner=player.GetComponent<MiningDefensePlanner3D>()!;
  void Frame(Key? key=null,bool mouse=false,Vector2? point=null){var raw=new RawInputSnapshot();if(key is {} k)raw.KeysDown.Add(k);if(mouse)raw.MouseButtonsDown.Add(MouseButton.Left);typeof(Input).GetMethod("UpdatePortable",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[raw,true]);typeof(Input).GetMethod("SetGameInputCaptured",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[true]);Input.SetGameViewPointer((point??new(640,360))/new Vector2(1280,720),new(1280,720),true);typeof(Time).GetMethod("Update",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[.05d]);typeof(Scene).GetMethod("UpdateInternal",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(scene,null);}
  Frame();Frame();Frame();Frame();
  var drill=scene.FindGameObject(op.DrillObjectId)!;var originalPlayer=player.Transform.WorldPosition;bool control=player.GetComponent<PlayerController3D>()!.Enabled;
  foreach(var offset in new[]{new Vector3(6.5f,0,0),new(-12,0,1.3f),new(0,0,-6),new(0,0,5)}){player.Transform.WorldPosition=drill.Transform.WorldPosition+offset;Frame();Check(ui.NearestScreen==MiningScreen.Drill,"drill is reachable from side "+offset);Frame(Key.E);Frame();Check(ui.Screen==MiningScreen.Drill,"E opens drill from that side");ui.Close();}
  player.Transform.WorldPosition=originalPlayer;Frame(Key.Tab);Frame();Check(camp.IsEditing&&Input.IsUiPointerRequested&&!player.GetComponent<PlayerController3D>()!.Enabled&&planner.SuppressWeaponFire,"Tab opens overhead arrangement, exposes cursor and suppresses movement/shooting");
  ui.OpenNearby();Check(ui.Screen==MiningScreen.None,"E cannot open machine panels while arranging");
  var press=scene.FindGameObject(ui.AmmoMachineObjectId)!;
  var camera=scene.ActiveCamera!;Vector2 ScreenPoint(Vector3 p){var v=Vector4.Transform(new Vector4(p,1),camera.GetRenderViewMatrix()*camera.GetProjectionMatrix(1280f/720));return new((v.X/v.W+1)*640,(1-v.Y/v.W)*360);}
  var pick=ScreenPoint(press.Transform.WorldPosition);Frame(mouse:true,point:pick);Frame(point:pick);Check(camp.SelectedObjectId==press.Id,"mouse click selects the visible machine through overhead projection");float priorYaw=camp.PreviewYaw;Frame(Key.Q,point:pick);Frame(point:pick);Check(camp.PreviewYaw!=priorYaw,"Q rotates the selected preview");camp.CancelMove();
  var original=press.Transform.WorldPosition;var rotation=press.Transform.WorldRotation;int ore=op.RefinedOre,rawOre=op.RawOre,ammo=player.GetComponent<FpsGunLab3D>()!.ReserveAmmo;int count=scene.GameObjects.Count();var children=scene.GameObjects.Where(o=>o.Parent==press).Select(o=>(o.Id,o.Transform.LocalPosition)).ToArray();
  Check(camp.BeginMove(press.Id),"existing ammo press can be selected");camp.SetPreview(new(100,0,100),0);Check(!camp.PreviewValid&&!camp.ConfirmMove()&&press.Transform.WorldPosition==original,"out-of-camp preview is rejected without moving the live machine");camp.SetPreview(drill.Transform.WorldPosition,0);Check(!camp.PreviewValid&&!camp.ConfirmMove(),"overlapping machines are rejected");camp.CancelMove();Check(press.Transform.WorldPosition==original&&scene.GameObjects.Count()==count,"cancel removes the complete ghost hierarchy and preserves the machine");
  bool Move(GameObject root,float yaw){if(!camp.BeginMove(root.Id))return false;var origin=root.Transform.WorldPosition;foreach(var delta in new[]{new Vector3(3,0,0),new(-3,0,0),new(0,0,-3),new(0,0,3),new(2,0,2),new(-2,0,-2),new(0,0,-7),new(6,0,0),new(-6,0,0),new(3,0,-6)}){camp.SetPreview(origin+delta,yaw);if(camp.PreviewValid&&camp.ConfirmMove())return true;Console.WriteLine("CANDIDATE "+root.Name+" "+delta+" "+camp.Status);}Console.WriteLine("MOVE STATUS "+root.Name+": "+camp.Status);return false;}
  Check(Move(press,15),"machine can move and rotate to a valid position while preserving navigation");Check(press.Transform.WorldPosition!=original&&press.Transform.WorldRotation!=rotation,"placement changes the real machine pose");Check(children.All(p=>scene.FindGameObject(p.Id)?.Parent==press&&scene.FindGameObject(p.Id)!.Transform.LocalPosition==p.LocalPosition)&&op.RefinedOre==ore&&op.RawOre==rawOre&&player.GetComponent<FpsGunLab3D>()!.ReserveAmmo==ammo,"moving retains child identities, bucket offsets and stock");
  Check(Move(drill,0),"massive drill can be repositioned with its fitted colliders and attached control point");
  Check(Move(scene.FindGameObject(ui.RefineryMachineObjectId)!,0),"refinery can be repositioned with its output bin");
  Check(Move(scene.FindGameObject("Company tent")!,0),"company tent can be repositioned with its computer and lighting");
  camp.PersistProgress=true;camp.SaveSlot="camp-native-check-"+Guid.NewGuid().ToString("N")+".json";Check(camp.SaveLayout(),"layout saves independently of company progress");var saved=press.Transform.WorldPosition;press.Transform.WorldPosition=original;camp.LoadLayout();Check(press.Transform.WorldPosition==saved,"saved layout restores the machine pose");File.Delete(Path.Combine(ByteEngine.Core.Runtime.GameSaveStorage.GetDirectory(scene.ProjectRoot!),camp.SaveSlot));camp.PersistProgress=false;
  typeof(MiningDefensePlanner3D).GetMethod("Spawn",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(planner,[MiningDefenseKind.Sentry,new Vector3(7,0,3),0f]);Frame();var defence=scene.GameObjects.Last(o=>o.GetComponent<MiningDefense3D>()!=null);int placements=planner.PlacedCount,available=planner.Available(MiningDefenseKind.Sentry);Check(Move(defence,30),"existing placed defence can be moved and rotated");Check(planner.Owns(defence)&&planner.PlacedCount==placements&&planner.Available(MiningDefenseKind.Sentry)==available,"relocation retains defence identity and licence usage");
  camp.ExitEdit();Check(planner.SuppressWeaponFire,"exit click cannot also fire the weapon in the same frame");Frame();Check(!camp.IsEditing&&!Input.IsUiPointerRequested&&player.GetComponent<PlayerController3D>()!.Enabled==control,"finishing restores gameplay controls and releases the UI cursor");
  Frame(Key.LeftAlt);var button=scene.FindGameObject(camp.EditButtonObjectId)!.GetComponent<UiWidget>()!;var rect=UiLayout.Resolve(button.GameObject,button.Anchor,button.Offset,button.Size,new(1280,720));Frame(Key.LeftAlt,mouse:true,point:rect.Position+rect.Size/2);Frame();Frame();Check(camp.IsEditing,"Alt plus the visible Arrange Camp button opens arrangement even without an available defence");camp.ExitEdit();
  planner.PersistProgress=true;planner.SaveSlot="camp-defence-check-"+Guid.NewGuid().ToString("N")+".json";planner.Save();var defenceFile=Path.Combine(ByteEngine.Core.Runtime.GameSaveStorage.GetDirectory(scene.ProjectRoot!),planner.SaveSlot);var state=System.Text.Json.JsonSerializer.Deserialize<MiningDefensePlanner3D.State>(File.ReadAllText(defenceFile))!;Check(planner.LastSaveSucceeded&&state.Placements!.Any(p=>p.Kind==MiningDefenseKind.Sentry&&Math.Abs(p.Yaw-30)<.01f),"defence save retains its moved position and rotation");File.Delete(defenceFile);planner.PersistProgress=false;
  typeof(MiningOperation3D).GetProperty("Phase")!.SetValue(op,MiningPhase.Drilling);Check(!camp.EnterEdit(),"camp cannot be rearranged during an operation");typeof(MiningOperation3D).GetProperty("Phase")!.SetValue(op,MiningPhase.Preparation);
  Check(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(Program.Root+"/Scenes/Main.bytescene")).SequenceEqual(hash),"checks do not overwrite the authored scene");host.UnloadScene();Console.WriteLine("CAMP NATIVE VERIFICATION COMPLETE");
 }
}
